INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Peripheriegeräte > Tastaturen und Mäuse
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Tastaturen und Mäuse unabhängig von den verfügbaren Schnittstellen ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Müssen mit USB oder PS/2 kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität verhindert Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl von Tastaturen und Mäusen immer ergonomische Aspekte berücksichtigt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Ergonomie ist optional, abhängig vom Nutzer"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die drahtlose Verbindung von Tastaturen und Mäusen immer zuverlässiger als eine kabelgebundene?', 2, '[{"text": "Nein", "correct": true, "because": "Kabelgebunden oft stabiler, keine Batterie nötig"}, {"text": "Ja", "correct": false, "because": "Drahtlos kann Störungen haben"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Tastaturen und Mäuse ohne Rücksicht auf die Betriebssystemkompatibilität ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Treiber oder Funktionen können inkompatibel sein"}, {"text": "Ja", "correct": false, "because": "Kompatibilität ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind teurere Tastaturen und Mäuse immer besser als günstigere Modelle?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität hängt von Anforderungen ab, nicht nur Preis"}, {"text": "Ja", "correct": false, "because": "Preis ≠ Qualität"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl von Tastaturen und Mäusen am wichtigsten?', 3, '[{"text": "Nutzungsanforderungen", "correct": true, "because": "Bestimmen Funktion und Komfort"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}, {"text": "Marke", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle wird für moderne Tastaturen und Mäuse am häufigsten verwendet?', 2, '[{"text": "USB", "correct": true, "because": "Universeller Standard"}, {"text": "PS/2", "correct": false, "because": "Veraltet"}, {"text": "Serial", "correct": false, "because": "Historisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft ist für Gaming-Mäuse entscheidend?', 2, '[{"text": "Hohe DPI", "correct": true, "because": "Erhöht Präzision und Reaktionsfähigkeit"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}, {"text": "Kabellänge", "correct": false, "because": "Weniger relevant bei Drahtlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tastaturtechnologie bietet die beste Reaktionszeit?', 3, '[{"text": "Mechanische Schalter", "correct": true, "because": "Direkte Rückmeldung und Schnelligkeit"}, {"text": "Membran", "correct": false, "because": "Langsamer, weicher"}, {"text": "Kapazitiv", "correct": false, "because": "Seltener, weniger präzise"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil von drahtlosen Tastaturen und Mäusen?', 2, '[{"text": "Flexibilität bei der Platzierung", "correct": true, "because": "Keine Kabelbegrenzung"}, {"text": "Geringere Kosten", "correct": false, "because": "Oft teurer"}, {"text": "Höhere Zuverlässigkeit", "correct": false, "because": "Kabelgebunden stabiler"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Auswahl von Tastaturen und Mäusen?', 4, '[{"text": "Schnittstellenkompatibilität", "correct": true, "because": "Muss zum System passen"}, {"text": "Ergonomie", "correct": true, "because": "Beeinflusst Komfort"}, {"text": "Nutzungszweck", "correct": true, "because": "z. B. Gaming oder Büro"}, {"text": "Gewicht der Geräte", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten mechanische Tastaturen?', 3, '[{"text": "Langlebigkeit", "correct": true, "because": "Robuste Schalter"}, {"text": "Bessere Rückmeldung", "correct": true, "because": "Taktile Reaktion"}, {"text": "Schnelle Reaktionszeit", "correct": true, "because": "Direkte Aktivierung"}, {"text": "Geringerer Preis", "correct": false, "because": "Teurer als Membran"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Auswahl von Tastaturen und Mäusen auftreten?', 3, '[{"text": "Inkompatibilität mit Ports", "correct": true, "because": "Falsche Schnittstelle"}, {"text": "Fehlende Treiber", "correct": true, "because": "Funktionen nicht verfügbar"}, {"text": "Unzureichende Ergonomie", "correct": true, "because": "Unbequem bei Langzeitnutzung"}, {"text": "Falsche Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale sind für Büro-Tastaturen und -Mäuse wichtig?', 4, '[{"text": "Leiser Betrieb", "correct": true, "because": "Stört nicht im Büro"}, {"text": "Ergonomisches Design", "correct": true, "because": "Schützt Gesundheit"}, {"text": "Lange Akkulaufzeit", "correct": true, "because": "Für Drahtlosmodelle"}, {"text": "Hohe DPI", "correct": false, "because": "Für Gaming, nicht Büro"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien werden für drahtlose Tastaturen und Mäuse genutzt?', 3, '[{"text": "Bluetooth", "correct": true, "because": "Kabellose Verbindung"}, {"text": "2.4-GHz-Funk", "correct": true, "because": "Mit USB-Empfänger"}, {"text": "Infrarot", "correct": true, "because": "Seltener, aber möglich"}, {"text": "Ethernet", "correct": false, "because": "Für Netzwerk, nicht Eingabe"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Mechanische Tastaturen sind langlebiger als Membranmodelle. b) Drahtlose Mäuse sind immer schneller als kabelgebundene.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mechanisch ja, Drahtlos nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) USB ist der aktuelle Standard für Tastaturen und Mäuse. b) Ergonomie ist bei Gaming-Tastaturen irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "USB ja, Ergonomie auch bei Gaming"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Hohe DPI bei Mäusen verbessert die Präzision. b) Alle Tastaturen sind mit jedem Betriebssystem kompatibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DPI ja, Kompatibilität variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Drahtlose Tastaturen nutzen oft Bluetooth. b) PS/2-Anschlüsse sind der aktuelle Standard.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bluetooth ja, PS/2 veraltet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Tastaturen und Mäuse müssen mit dem System kompatibel sein. b) Gaming-Mäuse benötigen keine hohe DPI.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kompatibilität ja, DPI für Gaming"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

